def edit(path, ops):
    text = io.open(path, encoding="utf-8").read()
    for old, new in ops:
        n = text.count(old)
        if n != 1:
            print(f"FAIL: anchor {n}x in {path}: {old[:80]!r}")
            sys.exit(1)
        text = text.replace(old, new)
    io.open(path, "w", encoding="utf-8").write(text)
    print(f"OK: {path} ({len(ops)} edits)")


